function drawGraphs(host, spec, tNow){
  const W=760, PH=118, GAP=16, PAD={l:56,r:16,t:12,b:22};
  const H=(PH+GAP)*3;
  const fns=[spec.a,spec.v,spec.s];
  let svg='<svg viewBox="0 0 '+W+' '+H+'" class="gsvg" role="img" aria-label="Acceleration, velocity and displacement against time">';
  fns.forEach((fn,gi)=>{
    const y0=gi*(PH+GAP);
    const N=260;
    let lo=Infinity, hi=-Infinity;
    const pts=[];
    for(let i=0;i<=N;i++){
      const t=spec.tmax*i/N, y=fn(t);
      pts.push([t,y]); if(y<lo)lo=y; if(y>hi)hi=y;
    }
    if(hi-lo<1e-9){ hi=lo+1; lo=lo-1; }
    const padY=(hi-lo)*0.14; lo-=padY; hi+=padY;
    if(lo>0) lo=0; if(hi<0) hi=0;
    const X=t=>PAD.l+(W-PAD.l-PAD.r)*(t/spec.tmax);
    const Y=v=>y0+PAD.t+(PH-PAD.t-PAD.b)*(1-(v-lo)/(hi-lo));
    // frame
    svg+='<rect x="'+PAD.l+'" y="'+(y0+PAD.t)+'" width="'+(W-PAD.l-PAD.r)+'" height="'+(PH-PAD.t-PAD.b)+'" class="gframe"/>';
    // zero line
    if(lo<0&&hi>0) svg+='<line x1="'+PAD.l+'" y1="'+Y(0)+'" x2="'+(W-PAD.r)+'" y2="'+Y(0)+'" class="gzero"/>';
    // curve, split at discontinuities
    let d="", prev=null;
    pts.forEach(([t,y],i)=>{
      const jump = prev!==null && Math.abs(y-prev)>(hi-lo)*0.5;
      d += (i===0||jump?"M":"L")+X(t).toFixed(1)+" "+Y(y).toFixed(1)+" ";
      prev=y;
    });
    svg+='<path d="'+d+'" class="gline"/>';
    // marks
    (spec.marks||[]).forEach(m=>{
      if(m<=spec.tmax) svg+='<line x1="'+X(m)+'" y1="'+(y0+PAD.t)+'" x2="'+X(m)+'" y2="'+(y0+PH-PAD.b)+'" class="gmark"/>';
    });
    // cursor
    const yv=fn(tNow);
    svg+='<line x1="'+X(tNow)+'" y1="'+(y0+PAD.t)+'" x2="'+X(tNow)+'" y2="'+(y0+PH-PAD.b)+'" class="gcur"/>';
    svg+='<circle cx="'+X(tNow)+'" cy="'+Y(yv)+'" r="4.5" class="gdot"/>';
    // labels
    svg+='<text x="6" y="'+(y0+PAD.t+11)+'" class="glab">'+spec.sym[gi]+'</text>';
    svg+='<text x="6" y="'+(y0+PAD.t+24)+'" class="gunit">'+spec.units[gi]+'</text>';
    svg+='<text x="'+(PAD.l-6)+'" y="'+(Y(hi-padY)+4)+'" class="gtick" text-anchor="end">'+(+(hi-padY).toPrecision(3))+'</text>';
    svg+='<text x="'+(PAD.l-6)+'" y="'+(Y(lo+padY)+4)+'" class="gtick" text-anchor="end">'+(+(lo+padY).toPrecision(3))+'</text>';
    svg+='<text x="'+(X(tNow)+6)+'" y="'+(y0+PAD.t+12)+'" class="gval">'+(+yv.toPrecision(4))+'</text>';
    if(gi===2) svg+='<text x="'+(W-PAD.r)+'" y="'+(y0+PH-4)+'" class="gtick" text-anchor="end">t [s]</text>';
  });
  svg+='</svg>';
  host.innerHTML=svg;
}

const TOL = 0.015;

/* ============================================================
   EXPRESSION ENGINE
   ============================================================ */
const CONSTANTS = {pi:Math.PI, e:Math.E, g:9.81};
const scope = Object.create(null);
let angleDeg = true;

function tokenize(src){
  const out=[]; let i=0;
  while(i<src.length){
    const c=src[i];
    if(/\s/.test(c)){i++;continue;}
    if(/[0-9.]/.test(c)){
      let j=i;
      while(j<src.length && /[0-9.]/.test(src[j])) j++;
      if(src[j]==='e'||src[j]==='E'){
        let k=j+1;
        if(src[k]==='+'||src[k]==='-') k++;
        if(/[0-9]/.test(src[k]||'')){ k++; while(k<src.length&&/[0-9]/.test(src[k]))k++; j=k; }
      }
      const t=src.slice(i,j);
      if(!/^\d*\.?\d*(?:[eE][+-]?\d+)?$/.test(t)||isNaN(parseFloat(t))) throw 0;
      out.push({k:'n',v:parseFloat(t)}); i=j; continue;
    }
    if(/[A-Za-z_]/.test(c)){
      let j=i; while(j<src.length&&/[A-Za-z_0-9]/.test(src[j])) j++;
      out.push({k:'id',v:src.slice(i,j)}); i=j; continue;
    }
    if('+-*/^%(),'.indexOf(c)>-1){ out.push({k:c}); i++; continue; }
    throw 0;
  }
  return out;
}
function ang(x){return angleDeg ? x*Math.PI/180 : x;}
function unang(x){return angleDeg ? x*180/Math.PI : x;}
const FN = {
  sin:x=>Math.sin(ang(x)), cos:x=>Math.cos(ang(x)), tan:x=>Math.tan(ang(x)),
  asin:x=>unang(Math.asin(x)), acos:x=>unang(Math.acos(x)), atan:x=>unang(Math.atan(x)),
  atan2:(y,x)=>unang(Math.atan2(y,x)),
  sqrt:Math.sqrt, abs:Math.abs, ln:Math.log, log:Math.log10, exp:Math.exp,
  round:x=>Math.round(x), floor:Math.floor, ceil:Math.ceil, min:Math.min, max:Math.max
};
function evaluate(src, vars){
  const t=tokenize(src);
  if(!t.length) throw 0;
  let p=0;
  const peek=()=>t[p], eat=k=>{ if(t[p]&&t[p].k===k){p++;return true;} return false; };
  function expr(){ let v=term(); for(;;){ if(eat('+')) v+=term(); else if(eat('-')) v-=term(); else return v; } }
  function term(){ let v=unary(); for(;;){ if(eat('*')) v*=unary(); else if(eat('/')) v/=unary(); else if(eat('%')) v%=unary(); else return v; } }
  function unary(){ if(eat('-')) return -unary(); if(eat('+')) return unary(); return power(); }
  function power(){ const b=atom(); if(eat('^')) return Math.pow(b, unary()); return b; }
  function atom(){
    const tk=peek(); if(!tk) throw 0;
    if(tk.k==='n'){p++; return tk.v;}
    if(tk.k==='('){p++; const v=expr(); if(!eat(')')) throw 0; return v;}
    if(tk.k==='id'){
      p++; const name=tk.v;
      if(peek()&&peek().k==='('){
        p++; const args=[];
        if(!eat(')')){ args.push(expr()); while(eat(',')) args.push(expr()); if(!eat(')')) throw 0; }
        const f=FN[name]; if(!f) throw 0;
        return f.apply(null,args);
      }
      if(vars && name in vars) return vars[name];
      if(name in CONSTANTS) return CONSTANTS[name];
      throw 0;
    }
    throw 0;
  }
  const val=expr();
  if(p!==t.length) throw 0;
  if(typeof val!=='number'||!isFinite(val)) throw 0;
  return val;
}
function evalLoose(src, vars){
  const s=String(src).trim();
  if(!s) return null;
  try{ return {v:evaluate(s,vars), unit:""}; }catch(e){}
  const parts=s.split(/\s+/);
  for(let cut=parts.length-1; cut>0; cut--){
    const head=parts.slice(0,cut).join(" ");
    if(!/[0-9]/.test(head)) break;
    try{ return {v:evaluate(head,vars), unit:parts.slice(cut).join(" ")}; }catch(e){}
  }
  return null;
}
function fmt(n){
  if(!isFinite(n)) return "—";
  const a=Math.abs(n);
  if(a!==0 && (a<1e-4 || a>=1e7)){
    const m=n.toExponential(4).split("e");
    return m[0].replace(/0+$/,"").replace(/\.$/,"")+"e"+m[1];
  }
  let s=n.toPrecision(7);
  if(s.indexOf(".")>-1) s=s.replace(/0+$/,"").replace(/\.$/,"");
  return s;
}

/* ============================================================
   STATE
   ============================================================ */
const KEY="mcen2003-t1-v1";
let active=0, store={};
try{ const a=+localStorage.getItem("mcen-active"); if(a>=0 && a<5) active=a; }catch(e){}
try{ store=JSON.parse(localStorage.getItem(KEY))||{}; }catch(e){ store={}; }

function qs(q){
  if(!store[q.id]) store[q.id]={};
  const s=store[q.id];
  ["ans","status","tried","first"].forEach(k=>{ if(!Array.isArray(s[k])) s[k]=[]; });
  if(!Array.isArray(s.pages)){
    s.pages=[{n: (typeof s.notes==="string" ? s.notes : (q.seed||"")), s: Array.isArray(s.strokes)?s.strokes:[]}];
    delete s.notes; delete s.strokes;
  }
  s.pages.forEach(p=>{ if(typeof p.n!=="string") p.n=""; if(!Array.isArray(p.s)) p.s=[]; });
  if(typeof s.page!=="number" || s.page<0 || s.page>=s.pages.length) s.page=0;
  if(typeof s.steps!=="number") s.steps=0;
  return s;
}
function qctx(){
  const base=QUESTIONS[active], s=qs(base);
  return {base:base, s:s, q:base, st:s};
}
function curPage(){ const s=qs(QUESTIONS[active]); return s.pages[s.page]; }
function triedCount(q,st){ return q.parts.filter((p,i)=>st.tried[i]).length; }
function isUnlocked(q,st){ return triedCount(q,st)===q.parts.length; }
function save(){ try{ localStorage.setItem(KEY, JSON.stringify(store)); localStorage.setItem("mcen-active", String(active)); }catch(e){} }
function esc(s){return String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}

/* ============================================================
   RAIL
   ============================================================ */
const railList=document.getElementById("railList");
document.getElementById("railCount").textContent=QUESTIONS.length+" questions";

function qState(q){
  const s=qs(q);
  if(!s.status.filter(Boolean).length) return "idle";
  if(q.parts.every((p,i)=>s.status[i]==="correct")) return "correct";
  if(s.status.some(x=>x==="wrong")) return "wrong";
  return "partial";
}
function buildRail(){
  railList.innerHTML="";
  QUESTIONS.forEach((q,i)=>{
    const li=document.createElement("li");
    const b=document.createElement("button");
    b.className="rail-item";
    b.setAttribute("aria-current", i===active?"true":"false");
    const st=qState(q);
    b.innerHTML='<span class="rail-num">'+q.code+'</span><span class="rail-topic">'+esc(q.topic)+'</span><span class="dot '+(st==="idle"?"":st)+'"></span>';
    b.addEventListener("click",()=>{ commitPad(); active=i; render(); window.scrollTo({top:0,behavior:"smooth"}); });
    li.appendChild(b); railList.appendChild(li);
  });
  const done=QUESTIONS.filter(q=>qState(q)==="correct").length;
  document.getElementById("meterFill").style.width=(done/QUESTIONS.length*100)+"%";
  document.getElementById("meterNum").textContent=done+" / "+QUESTIONS.length;
}

/* ============================================================
   QUESTION CARD
   ============================================================ */
const card=document.getElementById("qCard");
const LOCK='<svg class="ico" viewBox="0 0 16 16" aria-hidden="true"><rect x="3.2" y="7" width="9.6" height="7" rx="1.4" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M5.6 7V5.2a2.4 2.4 0 0 1 4.8 0V7" fill="none" stroke="currentColor" stroke-width="1.2"/><circle cx="8" cy="10.4" r="1" fill="currentColor"/></svg>';
const BOOK='<svg class="ico" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 4.2S6.8 2.8 4.6 2.8H2.2v9.4h2.4C6.8 12.2 8 13.4 8 13.4s1.2-1.2 3.4-1.2h2.4V2.8h-2.4C9.2 2.8 8 4.2 8 4.2Z" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/><path d="M8 4.4v9" stroke="currentColor" stroke-width="1.2"/></svg>';
const BULB='<svg class="ico" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 1.4a4.3 4.3 0 0 0-2.6 7.7c.5.4.8 1 .8 1.6v.4h3.6v-.4c0-.6.3-1.2.8-1.6A4.3 4.3 0 0 0 8 1.4Z" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M6.4 13h3.2M6.9 14.6h2.2" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>';

function render(){
  const C=qctx(), base=C.base, s=C.s, q=C.q, st=C.st;
  const traps = TRAPS[base.id] || null;
  const unlocked=isUnlocked(q,st);
  let h="";
  h+='<div class="q-head"><span class="q-index">'+q.code+'</span><span class="label q-topic">'+esc(q.topic)+'</span>';
  h+='</div>';
  h+='<h2 class="q-title">'+esc(q.title)+'</h2>';
  esc(q.statement).split("\n\n").forEach(par=>{ h+='<p class="q-statement">'+par+'</p>'; });
  if(q.fig) h+='<figure class="figure">'+q.fig+'<figcaption>'+esc(q.figCap||"")+'</figcaption></figure>';
  h+='<div class="given"><span class="label" style="align-self:center">Given</span>';
  q.given.forEach(g=>{ h+='<span class="given-chip">'+esc(g[0])+' = <b>'+esc(g[1])+'</b></span>'; });
  h+='</div>';

  if(base.sketch && !st.tried.some(Boolean)){
    h+='<div class="nudge"><b>Sketch it first.</b> '+esc(base.sketch)+
       ' <button class="linky" id="toDraw">Open the drawing page</button></div>';
  }

  h+='<div class="q-actions"><button class="hint-btn" id="hintBtn">'+BULB+(s.hint?"Hide the idea":"Idea — how do I start?")+'</button>'+
     '<button class="sol-btn'+(unlocked?'':' locked')+'" id="jumpSol">'+
     (unlocked ? BOOK+(st.sol?"Hide the solution":"Show the solution") : LOCK+"Solution — locked until you try")+'</button>';
  h+='</div>';

  if(s.hint){
    h+='<div class="hint-panel"><h4>Approach</h4><p>'+esc(q.hint.approach)+'</p><h4>Formulas you need</h4><div class="formulas">';
    q.hint.formulas.forEach(f=>{ h+='<div class="formula">'+esc(f)+'</div>'; });
    h+='</div>';
    if(q.hint.plan){
      h+='<h4>Your plan — every step, no numbers</h4><ol class="plan">';
      q.hint.plan.forEach(p=>{ h+='<li>'+esc(p)+'</li>'; });
      h+='</ol>';
    }
    h+='<p class="hint-tip">Watch out: '+esc(q.hint.tip)+'</p></div>';
  }

  h+='<div class="answers"><div class="answers-head"><span class="label">Your answers</span>'+
     '<span class="label" style="text-transform:none;letter-spacing:0;font-weight:400">Type a number, or an expression if you would rather let it do the arithmetic.</span></div>';

  h+='<div class="why"><label class="label" for="whyBox">Before you check — in one line, which equation are you using and why?</label>'+
     '<input id="whyBox" placeholder="e.g. v = u + at, because the acceleration is constant in this phase" value="'+esc(s.why||"")+'"></div>';

  q.parts.forEach((p,i)=>{
    const stt=st.status[i]||"";
    h+='<div class="ans-row '+stt+'" data-i="'+i+'">';
    h+='<label class="ans-label" for="ans'+i+'">'+esc(p.label)+'</label>';
    if(p.choices){
      h+='<div class="choices">';
      p.choices.forEach((c,ci)=>{
        const picked=String(st.ans[i])===String(ci);
        const showRight=st["rev"+i]&&ci===p.value;
        h+='<button class="choice'+(showRight?' isright':'')+'" data-choice="'+i+'" data-ci="'+ci+'" aria-pressed="'+(picked?"true":"false")+'">'+esc(c)+'</button>';
      });
      h+='</div>';
    }else{
      h+='<div class="ans-input-wrap"><input class="ans-input" id="ans'+i+'" inputmode="text" spellcheck="false" autocomplete="off" placeholder="'+esc(p.ph||"your answer")+'" value="'+esc(st.ans[i]||"")+'"><span class="ans-unit">'+esc(p.unit)+'</span></div>';
    }
    if(stt==="correct") h+='<span class="verdict correct">✓ Correct'+(st.first[i]==="y"?' — first go':'')+'</span>';
    if(stt==="wrong"){
      const why = st["why"+i];
      if(why) h+='<div class="diag"><b>Not quite — here is what happened.</b> '+esc(why)+'</div>';
      h+='<span class="verdict wrong">✗ Not right yet — <button class="tap-hint" data-reveal="'+i+'">tap to see the answer</button></span>';
    }
    if(st["rev"+i]&&!p.choices) h+='<div class="reveal-box">'+fmt(p.value)+' '+esc(p.unit)+' <span>(±'+(TOL*100)+'%)</span></div>';
    h+='</div>';
  });
  h+='<div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:4px"><button class="check-btn" id="checkBtn">Check my answers</button><button class="ghost-btn" id="clearAns">Clear</button></div></div>';

  h+='<div class="solution" id="solBlock">';
  if(!unlocked){
    const n=triedCount(q,st), tot=q.parts.length;
    h+='<div class="lockbox"><h4>'+LOCK+'The solution is locked</h4>'+
       '<p>Work it out yourself first. Put an answer in every part above and press <b>Check my answers</b> — right or wrong makes no difference, an attempt is all it takes. If you have no idea where to start, open the <b>idea</b> button: it gives you the approach, the formulas, and a step-by-step plan without the numbers.</p>'+
       '<div class="trybar"><div class="trydots">';
    q.parts.forEach((p,i)=>{ h+='<span class="trydot'+(st.tried[i]?' on':'')+'"></span>'; });
    h+='</div><span class="trycount">'+n+' of '+tot+' parts attempted</span>'+
       (n<tot?'<button class="ghost-btn" id="toAnswers" style="padding:5px 12px;margin-left:auto">Go to the answers</button>':'')+
       '</div></div>';
  }else if(!st.sol){
    h+='<div class="sol-locked"><button class="ghost-btn" id="revealBtn">Reveal the solution</button><p>You have had a go at every part — the solution is yours whenever you want it.</p></div>';
  }else{
    const hasOrig = base.original;
    const hasGraph = GRAPHS[base.id];
    let mode = st.mode||"steps";
    if(mode==="full" && !hasOrig) mode="steps";
    if(mode==="graph" && !hasGraph) mode="steps";
    h+='<div class="sol-bar"><span class="label">Solution</span><div class="tabs" role="tablist">'+
       '<button class="tab" role="tab" data-mode="steps" aria-selected="'+(mode==="steps")+'">Step by step</button>'+
       (hasOrig?'<button class="tab" role="tab" data-mode="full" aria-selected="'+(mode==="full")+'">Original solution</button>':'')+
       (hasGraph?'<button class="tab" role="tab" data-mode="graph" aria-selected="'+(mode==="graph")+'">Motion graphs</button>':'')+
       '</div><button class="ghost-btn" id="hideSteps" style="margin-left:auto;padding:5px 12px">Hide</button></div>';
    if(mode==="steps"){
      const cp=CONCEPT[base.id], wy=WHY[base.id]||[];
      if(cp){
        h+='<div class="concept"><h4>The idea behind this question</h4><p class="cp-head">'+esc(cp.head)+'</p>'+
           '<p>'+esc(cp.body)+'</p><p class="cp-carry"><b>Carry this forward:</b> '+esc(cp.carry)+'</p></div>';
      }
      if(wy.length) h+='<div class="reasonbar"><button class="ghost-btn" id="allWhy" style="padding:5px 12px">'+
        (st.whyAll?"Hide all reasoning":"Show the reasoning on every step")+'</button>'+
        '<span class="rnote">Each step can explain itself — open one when a line does not make sense.</span></div>';
      h+='<ol class="steps">';
      q.steps.slice(0,st.steps||1).forEach((sp,i)=>{
        h+='<li class="step"><span class="step-n">'+(i+1)+'</span><div><p class="step-t">'+esc(sp.t)+'</p><p class="step-d">'+esc(sp.d)+'</p>';
        if(wy[i]){
          const open = st.whyAll || st["w"+i];
          h+='<button class="whytog'+(open?' open':'')+'" data-why="'+i+'">'+(open?"▾":"▸")+' Why this step?</button>';
          if(open) h+='<div class="whytext">'+esc(wy[i])+'</div>';
        }
        h+='</div></li>';
      });
      h+='</ol><div style="display:flex;gap:9px;margin-top:14px;flex-wrap:wrap">';
      if((st.steps||1)<q.steps.length) h+='<button class="check-btn" id="nextStep">Next step &rsaquo;</button><button class="ghost-btn" id="allSteps">Show all steps</button>';
      h+='</div>';
    }else if(mode==="full"){
      h+='<div class="original"><span class="src">'+base.code+' — solution as issued in the unit solution sheet</span><pre>'+esc(base.original)+'</pre></div>';
    }else{
      const g=GRAPHS[base.id];
      h+='<div class="graphwrap"><p class="gnote">Drag the slider to move through the motion. Watch how the <b>area</b> under '+g.sym[0]+
         ' builds '+g.sym[1]+', and the area under '+g.sym[1]+' builds '+g.sym[2]+' — and how '+g.sym[2]+
         ' peaks exactly where '+g.sym[1]+' crosses zero.</p>'+
         '<div id="graphMount"></div>'+
         '<div class="grow"><input type="range" id="gSlide" min="0" max="'+g.tmax+'" step="0.02" value="'+(st.gt||0)+'">'+
         '<span class="gtime mono">t = <b id="gTime">'+(+(st.gt||0)).toFixed(2)+'</b> s</span></div></div>';
    }
  }
  h+='</div>';
  card.innerHTML=h;

  document.getElementById("hintBtn").addEventListener("click",()=>{ s.hint=!s.hint; if(s.hint) s.everHint=true; save(); render(); });
  document.getElementById("checkBtn").addEventListener("click",checkAnswers);
  document.getElementById("clearAns").addEventListener("click",()=>{
    st.ans=[]; st.status=[]; q.parts.forEach((p,i)=>{ delete st["rev"+i]; delete st["why"+i]; }); save(); render();
  });
  const wb=document.getElementById("whyBox");
  if(wb) wb.addEventListener("input",()=>{ s.why=wb.value; save(); });
  const td=document.getElementById("toDraw");
  if(td) td.addEventListener("click",()=>{ selectTab("draw"); document.getElementById("workPad").scrollIntoView({behavior:"smooth",block:"start"}); });
  card.querySelectorAll(".ans-input").forEach(el=>{
    const i=+el.closest(".ans-row").dataset.i;
    el.addEventListener("input",()=>{ st.ans[i]=el.value; save(); });
    el.addEventListener("keydown",ev=>{ if(ev.key==="Enter"){ev.preventDefault();checkAnswers();} });
  });
  card.querySelectorAll("[data-choice]").forEach(b=>{
    b.addEventListener("click",()=>{ st.ans[+b.dataset.choice]=b.dataset.ci; save(); render(); });
  });
  card.querySelectorAll("[data-reveal]").forEach(b=>{
    b.addEventListener("click",()=>{ st["rev"+b.dataset.reveal]=true; save(); render(); });
  });
  card.querySelectorAll(".ans-row.wrong .ans-input").forEach(el=>{
    el.addEventListener("focus",()=>{ st["rev"+el.closest(".ans-row").dataset.i]=true; save(); render(); });
  });
  document.getElementById("jumpSol").addEventListener("click",()=>{
    if(!unlocked){ document.getElementById("solBlock").scrollIntoView({behavior:"smooth",block:"center"}); return; }
    if(st.sol){ st.sol=0; save(); render(); } else openSol();
  });
  function openSol(){
    st.sol=1; st.everSol=true; s.everSol=true; if(!st.steps) st.steps=1; save(); render();
    requestAnimationFrame(()=>{ const el=document.getElementById("solBlock"); if(el) el.scrollIntoView({behavior:"smooth",block:"start"}); });
  }
  const ta=document.getElementById("toAnswers");
  if(ta) ta.addEventListener("click",()=>{
    const first=card.querySelector('.ans-row:not(.correct):not(.wrong)')||card.querySelector('.ans-row');
    if(first){ first.scrollIntoView({behavior:"smooth",block:"center"}); const inp=first.querySelector(".ans-input"); if(inp) setTimeout(()=>inp.focus(),320); }
  });
  const rb=document.getElementById("revealBtn"); if(rb) rb.addEventListener("click",openSol);
  card.querySelectorAll("[data-mode]").forEach(b=>{
    b.addEventListener("click",()=>{ st.mode=b.dataset.mode; if(!st.steps) st.steps=1; save(); render(); });
  });
  card.querySelectorAll("[data-why]").forEach(b=>{
    b.addEventListener("click",()=>{ const k="w"+b.dataset.why; st[k]=!st[k]; save(); render(); });
  });
  const aw=document.getElementById("allWhy");
  if(aw) aw.addEventListener("click",()=>{
    st.whyAll=!st.whyAll;
    if(!st.whyAll) q.steps.forEach((sp,i)=>{ delete st["w"+i]; });
    save(); render();
  });
  const ns=document.getElementById("nextStep"); if(ns) ns.addEventListener("click",()=>{ st.steps=Math.min((st.steps||1)+1,q.steps.length); save(); render(); });
  const as=document.getElementById("allSteps"); if(as) as.addEventListener("click",()=>{ st.steps=q.steps.length; save(); render(); });
  const hs=document.getElementById("hideSteps"); if(hs) hs.addEventListener("click",()=>{ st.sol=0; save(); render(); });

  const gm=document.getElementById("graphMount");
  if(gm){
    const g=GRAPHS[base.id], sl=document.getElementById("gSlide");
    const paint=()=>{ drawGraphs(gm,g,+sl.value); document.getElementById("gTime").textContent=(+sl.value).toFixed(2); };
    sl.addEventListener("input",()=>{ st.gt=+sl.value; paint(); });
    sl.addEventListener("change",save);
    paint();
  }

  loadPad();
  buildRail();
}

function checkAnswers(){
  const C=qctx(), base=C.base, s=C.s, q=C.q, st=C.st;
  const traps=TRAPS[base.id]||null;
  q.parts.forEach((p,i)=>{
    const raw=st.ans[i];
    delete st["why"+i];
    if(raw===undefined||raw===null||String(raw).trim()===""){ st.status[i]=""; return; }
    const firstGo = !st.tried[i];
    st.tried[i]=true;
    if(p.choices){
      st.status[i]=Number(raw)===p.value ? "correct" : "wrong";
      if(st.status[i]==="wrong" && CHOICE_TRAP[base.id] && CHOICE_TRAP[base.id][i])
        st["why"+i]=CHOICE_TRAP[base.id][i];
    }else{
      const r=evalLoose(raw, scope);
      if(!r){ st.status[i]="wrong"; st["why"+i]="I could not read that as a number. Type a plain value like 44.7, or an expression like 90 - 10*8."; }
      else{
        const denom=Math.abs(p.value)||1;
        st.status[i]=Math.abs(r.v-p.value)/denom<=TOL ? "correct" : "wrong";
        if(st.status[i]==="wrong"){
          if(traps && traps[i]) for(const t of traps[i]){
            const dn=Math.abs(t[0])||1;
            if(Math.abs(r.v-t[0])/dn<=0.006){ st["why"+i]=t[1]; break; }
          }
          if(!st["why"+i] && Math.abs(r.v+p.value)/denom<=TOL)
            st["why"+i]="Right magnitude, wrong sign. Check which direction you called positive — the sign is part of the answer.";
          if(!st["why"+i]){
            const ratio=Math.abs(r.v)/Math.abs(p.value||1);
            const powers=[[1000,"a factor of 1000 out — check mm against m, or kPa against Pa"],
                          [1e6,"a factor of a million out — check your MPa/GPa or mm²/m² conversion"],
                          [3.6,"a factor of 3.6 out — that is the km/h to m/s conversion"],
                          [60,"a factor of 60 out — check a per-minute against a per-second quantity"],
                          [2*Math.PI,"a factor of 2\u03C0 out — check radians against revolutions"]];
            for(const [f,msg] of powers){
              if(Math.abs(ratio-f)/f<=0.02 || Math.abs(ratio-1/f)*f<=0.02){ st["why"+i]="Your number is "+msg+"."; break; }
            }
          }
        }
      }
    }
    if(firstGo) st.first[i] = st.status[i]==="correct" ? "y" : "n";
    if(st.status[i]==="correct"){ delete st["rev"+i]; delete st["why"+i]; }
  });
  save(); render();
}

/* ============================================================
   WORKING PAD
   ============================================================ */
const padInput=document.getElementById("padInput");
const padOut=document.getElementById("padOut");

const pageBar=document.getElementById("pageBar");
function buildPages(){
  const s=qs(QUESTIONS[active]);
  let h="";
  s.pages.forEach((p,i)=>{
    h+='<button class="pchip" data-page="'+i+'" aria-current="'+(i===s.page)+'" title="Page '+(i+1)+'">'+(i+1)+'</button>';
  });
  h+='<button class="pchip add" id="addPage" title="Add another page">+ Page</button>';
  if(s.pages.length>1) h+='<button class="pchip del" id="delPage" title="Delete this page">Delete page</button>';
  pageBar.innerHTML=h;
  pageBar.querySelectorAll("[data-page]").forEach(b=>{
    b.addEventListener("click",()=>{ commitPad(); s.page=+b.dataset.page; save(); loadPad(); });
  });
  document.getElementById("addPage").addEventListener("click",()=>{
    commitPad(); s.pages.push({n:"",s:[]}); s.page=s.pages.length-1; save(); loadPad(); padInput.focus();
  });
  const dp=document.getElementById("delPage");
  if(dp) dp.addEventListener("click",()=>{
    if(dp.dataset.armed!=="1"){
      dp.dataset.armed="1"; dp.textContent="Tap again to delete";
      setTimeout(()=>{ if(dp.isConnected){ dp.dataset.armed="0"; dp.textContent="Delete page"; } },3500);
      return;
    }
    s.pages.splice(s.page,1); s.page=Math.max(0,s.page-1); save(); loadPad();
  });
}
function loadPad(){
  padInput.value=curPage().n||"";
  buildPages(); runPad(); loadBoard();
}
function commitPad(){ curPage().n=padInput.value; save(); }
function runPad(){
  const s=qs(QUESTIONS[active]);
  const lines=padInput.value.split("\n");
  for(const k in scope) delete scope[k];
  // earlier pages feed their variables forward into this one
  for(let pi=0; pi<s.page; pi++) s.pages[pi].n.split("\n").forEach(evalLine);
  let html="";
  lines.forEach(line=>{
    const body=line.split("#")[0];
    if(!body.trim()){ html+="<div></div>"; return; }
    const m=body.match(/^\s*([A-Za-z_][A-Za-z_0-9]*)\s*=\s*(.+)$/);
    let name=null, rhs;
    if(m){ name=m[1]; rhs=m[2]; } else { rhs=body.replace(/=\s*$/,""); }
    const res=evalLoose(rhs, scope);
    if(!res){ html+='<div class="err"></div>'; return; }
    if(name) scope[name]=res.v;
    html+='<div>'+esc(fmt(res.v))+(res.unit?' <span class="u">'+esc(res.unit)+'</span>':'')+'</div>';
  });
  padOut.innerHTML=html;
  padInput.style.height=(Math.max(lines.length+2, focusOn?34:22)*30+30)+"px";
  paintVars();
}
function evalLine(line){
  const body=line.split("#")[0];
  if(!body.trim()) return;
  const m=body.match(/^\s*([A-Za-z_][A-Za-z_0-9]*)\s*=\s*(.+)$/);
  if(!m) return;
  const r=evalLoose(m[2], scope);
  if(r) scope[m[1]]=r.v;
}
padInput.addEventListener("input",()=>{ runPad(); commitPad(); });

