/* ============================================================
   DRAWING BOARD — pressure, smoothing, incremental rendering
   ============================================================ */
const board=document.getElementById("board"), ctx=board.getContext("2d");
let penColor="ink", penWidth=2.6, erasing=false, drawing=false, current=null, activeId=null;
function inkColor(){ return getComputedStyle(document.documentElement).getPropertyValue("--ink").trim()||"#161B21"; }

function sizeBoard(){
  const r=board.getBoundingClientRect(); if(!r.width) return;
  const dpr=Math.min(window.devicePixelRatio||1, 2.5);
  board.width=Math.round(r.width*dpr); board.height=Math.round(r.height*dpr);
  ctx.setTransform(dpr,0,0,dpr,0,0); redraw();
}
function strokeColor(st){ return st.c==="ink" ? inkColor() : st.c; }
function widthAt(st,pr){ return st.w*(0.45+1.1*(pr==null?0.5:pr)); }
function drawSeg(st,a,b){
  ctx.strokeStyle=strokeColor(st);
  ctx.lineWidth=(widthAt(st,a[2])+widthAt(st,b[2]))/2;
  ctx.lineCap="round"; ctx.lineJoin="round";
  ctx.beginPath(); ctx.moveTo(a[0],a[1]); ctx.lineTo(b[0],b[1]); ctx.stroke();
}
function drawDot(st,a){
  ctx.fillStyle=strokeColor(st);
  ctx.beginPath(); ctx.arc(a[0],a[1],widthAt(st,a[2])/2,0,Math.PI*2); ctx.fill();
}
function redraw(){
  ctx.clearRect(0,0,board.width,board.height);
  curPage().s.forEach(st=>{
    if(st.p.length===1){ drawDot(st,st.p[0]); return; }
    for(let k=1;k<st.p.length;k++) drawSeg(st,st.p[k-1],st.p[k]);
  });
}
function loadBoard(){ if(!document.getElementById("padDraw").hidden) sizeBoard(); else redraw(); }
function pos(e){
  const r=board.getBoundingClientRect();
  const pr = (e.pressure!=null && e.pressure>0) ? e.pressure : 0.5;
  return [e.clientX-r.left, e.clientY-r.top, pr];
}

board.addEventListener("pointerdown",e=>{
  if(penOnly && e.pointerType!=="pen") return;      // palm rejection, only when the teacher-facing toggle is on
  if(drawing) return;                                // ignore a second finger mid-stroke
  e.preventDefault();
  activeId=e.pointerId;
  try{ board.setPointerCapture(e.pointerId); }catch(err){}
  drawing=true;
  const p=pos(e);
  if(erasing){ eraseAt(p); return; }
  current={c:penColor,w:penWidth,p:[p]};
  curPage().s.push(current);
  drawDot(current,p);
},{passive:false});

board.addEventListener("pointermove",e=>{
  if(!drawing || e.pointerId!==activeId) return;
  e.preventDefault();
  if(erasing){ eraseAt(pos(e)); return; }
  // getCoalescedEvents keeps fast strokes smooth instead of straight-lining between samples
  const evs = (typeof e.getCoalescedEvents==="function") ? e.getCoalescedEvents() : [e];
  for(const ev of (evs.length?evs:[e])){
    const p=pos(ev), last=current.p[current.p.length-1];
    if(Math.hypot(p[0]-last[0],p[1]-last[1])<0.6) continue;
    current.p.push(p);
    drawSeg(current,last,p);
  }
},{passive:false});

function endStroke(e){
  if(!drawing) return;
  if(e && e.pointerId!==activeId) return;
  drawing=false; current=null; activeId=null;
  save();
}
board.addEventListener("pointerup",endStroke);
board.addEventListener("pointercancel",endStroke);
// NB: no pointerleave handler — on iPadOS it can fire straight after pointerdown and kill the stroke

function eraseAt(pt){
  const pg=curPage(), before=pg.s.length;
  pg.s=pg.s.filter(st=>!st.p.some(p=>Math.hypot(p[0]-pt[0],p[1]-pt[1])<16));
  if(pg.s.length!==before) redraw();
}

