/* ============================================================
   CALCULATOR + FORMULA SHEET
   ============================================================ */
const calcPanel=document.getElementById("calcPanel"), calcIn=document.getElementById("calcIn"),
      calcRes=document.getElementById("calcRes"), calcToggle=document.getElementById("calcToggle");
let ans=0;
const KEYS=[
  ["sin(","sin","fn"],["cos(","cos","fn"],["tan(","tan","fn"],["sqrt(","√","fn"],["^","^","op"],
  ["7","7"],["8","8"],["9","9"],["/","÷","op"],["(","(","op"],
  ["4","4"],["5","5"],["6","6"],["*","×","op"],[")",")","op"],
  ["1","1"],["2","2"],["3","3"],["-","−","op"],["pi","π","fn"],
  ["0","0"],[".","."],["g","g","fn"],["+","+","op"],["=","=","eq"],
  ["e","e","fn"],["ln(","ln","fn"],["log(","log","fn"],["ans","ans","fn"],["⌫","⌫","del"]
];
const keysEl=document.getElementById("keys");
KEYS.forEach(k=>{
  const b=document.createElement("button");
  b.className="key"+(k[2]?" "+k[2]:""); b.textContent=k[1];
  b.addEventListener("click",()=>{
    if(k[0]==="="){ pushCalc(); return; }
    if(k[0]==="⌫"){ calcIn.value=calcIn.value.slice(0,-1); calcLive(); return; }
    calcIn.value+=k[0]; calcLive(); calcIn.focus();
  });
  keysEl.appendChild(b);
});
function calcLive(){
  const v=calcIn.value.trim();
  if(!v){ calcRes.textContent=""; calcRes.classList.remove("err"); return; }
  const r=evalLoose(v, Object.assign({ans:ans}, scope));
  if(r){ calcRes.textContent=fmt(r.v)+(r.unit?" "+r.unit:""); calcRes.classList.remove("err"); }
  else { calcRes.textContent="keep typing…"; calcRes.classList.add("err"); }
}
function pushCalc(){
  const r=evalLoose(calcIn.value, Object.assign({ans:ans}, scope));
  if(r){ ans=r.v; calcIn.value=fmt(r.v); calcLive(); }
}
calcIn.addEventListener("input",calcLive);
calcIn.addEventListener("keydown",e=>{ if(e.key==="Enter"){e.preventDefault();pushCalc();} });
document.getElementById("angleMode").addEventListener("click",e=>{
  angleDeg=!angleDeg; e.target.textContent=angleDeg?"DEG":"RAD"; calcLive(); runPad();
});
function openCalc(open){
  calcPanel.hidden=!open;
  calcToggle.setAttribute("aria-pressed",open?"true":"false");
  calcToggle.classList.toggle("active",open);
  if(open) calcIn.focus();
}
calcToggle.addEventListener("click",()=>openCalc(calcPanel.hidden));
document.getElementById("calcClose").addEventListener("click",()=>openCalc(false));
function paintVars(){
  const el=document.getElementById("calcVars"), names=Object.keys(scope);
  el.innerHTML = names.length
    ? names.map(n=>'<span class="var-chip"><b>'+esc(n)+'</b> '+esc(fmt(scope[n]))+'</span>').join("")
    : '<span class="var-chip">Define values in the working pad and use them here</span>';
}
const fsPanel=document.getElementById("fsPanel"), fsToggle=document.getElementById("fsToggle");
fsToggle.addEventListener("click",()=>{
  const open=fsPanel.hidden;
  fsPanel.hidden=!open;
  fsToggle.setAttribute("aria-pressed",open?"true":"false");
  fsToggle.classList.toggle("active",open);
});

/* ============================================================
   Minimal .docx writer — stored (uncompressed) ZIP + OOXML
   ============================================================ */
const CRC_TABLE = (function(){
  const t=new Uint32Array(256);
  for(let n=0;n<256;n++){ let c=n; for(let k=0;k<8;k++) c = c&1 ? 0xEDB88320^(c>>>1) : c>>>1; t[n]=c>>>0; }
  return t;
})();
function crc32(u8){
  let c=0xFFFFFFFF;
  for(let i=0;i<u8.length;i++) c = CRC_TABLE[(c^u8[i])&0xFF] ^ (c>>>8);
  return (c^0xFFFFFFFF)>>>0;
}
function utf8(str){ return new TextEncoder().encode(str); }
function b64ToBytes(b64){
  const bin=atob(b64); const u=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i);
  return u;
}
function zipStore(files){
  const enc=files.map(f=>({name:utf8(f.name), data:f.data, crc:crc32(f.data)}));
  let total=0;
  enc.forEach(f=>{ total += 30+f.name.length+f.data.length + 46+f.name.length; });
  total += 22;
  const out=new Uint8Array(total);
  const dv=new DataView(out.buffer);
  let off=0; const central=[];
  enc.forEach(f=>{
    const start=off;
    dv.setUint32(off,0x04034b50,true); off+=4;
    dv.setUint16(off,20,true); off+=2;          // version needed
    dv.setUint16(off,0x0800,true); off+=2;      // UTF-8 names
    dv.setUint16(off,0,true); off+=2;           // stored
    dv.setUint16(off,0,true); off+=2;           // time
    dv.setUint16(off,0x21,true); off+=2;        // date (1980-01-01)
    dv.setUint32(off,f.crc,true); off+=4;
    dv.setUint32(off,f.data.length,true); off+=4;
    dv.setUint32(off,f.data.length,true); off+=4;
    dv.setUint16(off,f.name.length,true); off+=2;
    dv.setUint16(off,0,true); off+=2;
    out.set(f.name,off); off+=f.name.length;
    out.set(f.data,off); off+=f.data.length;
    central.push({f,start});
  });
  const cdStart=off;
  central.forEach(({f,start})=>{
    dv.setUint32(off,0x02014b50,true); off+=4;
    dv.setUint16(off,20,true); off+=2;
    dv.setUint16(off,20,true); off+=2;
    dv.setUint16(off,0x0800,true); off+=2;
    dv.setUint16(off,0,true); off+=2;
    dv.setUint16(off,0,true); off+=2;
    dv.setUint16(off,0x21,true); off+=2;
    dv.setUint32(off,f.crc,true); off+=4;
    dv.setUint32(off,f.data.length,true); off+=4;
    dv.setUint32(off,f.data.length,true); off+=4;
    dv.setUint16(off,f.name.length,true); off+=2;
    dv.setUint16(off,0,true); off+=2;  // extra
    dv.setUint16(off,0,true); off+=2;  // comment
    dv.setUint16(off,0,true); off+=2;  // disk
    dv.setUint16(off,0,true); off+=2;  // internal attrs
    dv.setUint32(off,0,true); off+=4;  // external attrs
    dv.setUint32(off,start,true); off+=4;
    out.set(f.name,off); off+=f.name.length;
  });
  const cdSize=off-cdStart;
  dv.setUint32(off,0x06054b50,true); off+=4;
  dv.setUint16(off,0,true); off+=2;                 // this disk
  dv.setUint16(off,0,true); off+=2;                 // disk with central dir
  dv.setUint16(off,central.length,true); off+=2;    // entries on this disk
  dv.setUint16(off,central.length,true); off+=2;    // total entries
  dv.setUint32(off,cdSize,true); off+=4;
  dv.setUint32(off,cdStart,true); off+=4;
  dv.setUint16(off,0,true); off+=2;                 // comment length
  return out;
}

const XML_ESC = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));

/* --- document building blocks --- */
function run(text, o){
  o=o||{};
  let rpr='<w:rPr>';
  if(o.font) rpr+='<w:rFonts w:ascii="'+o.font+'" w:hAnsi="'+o.font+'" w:cs="'+o.font+'"/>';
  if(o.b) rpr+='<w:b/>';
  if(o.i) rpr+='<w:i/>';
  if(o.caps) rpr+='<w:smallCaps/>';
  if(o.color) rpr+='<w:color w:val="'+o.color+'"/>';
  if(o.sz) rpr+='<w:sz w:val="'+o.sz+'"/><w:szCs w:val="'+o.sz+'"/>';
  rpr+='</w:rPr>';
  const parts=String(text==null?"":text).split("\n");
  let body="";
  parts.forEach((p,i)=>{
    if(i) body+='<w:br/>';
    body+='<w:t xml:space="preserve">'+XML_ESC(p)+'</w:t>';
  });
  return '<w:r>'+rpr+body+'</w:r>';
}
function para(runs, o){
  o=o||{};
  let ppr='<w:pPr>';
  ppr+='<w:spacing w:before="'+(o.before||0)+'" w:after="'+(o.after==null?100:o.after)+'" w:line="'+(o.line||260)+'" w:lineRule="auto"/>';
  if(o.align) ppr+='<w:jc w:val="'+o.align+'"/>';
  if(o.border) ppr+='<w:pBdr><w:bottom w:val="single" w:sz="'+(o.borderSz||8)+'" w:space="2" w:color="'+(o.borderColor||'0F5F7D')+'"/></w:pBdr>';
  if(o.shade) ppr+='<w:shd w:val="clear" w:color="auto" w:fill="'+o.shade+'"/>';
  if(o.keepNext) ppr+='<w:keepNext/>';
  if(o.indent) ppr+='<w:ind w:left="'+o.indent+'"/>';
  ppr+='</w:pPr>';
  return '<w:p>'+ppr+(Array.isArray(runs)?runs.join(""):runs)+'</w:p>';
}
function cell(content, o){
  o=o||{};
  return '<w:tc><w:tcPr><w:tcW w:w="'+(o.w||3000)+'" w:type="dxa"/>'+
    (o.shade?'<w:shd w:val="clear" w:color="auto" w:fill="'+o.shade+'"/>':'')+
    '<w:tcBorders><w:bottom w:val="single" w:sz="4" w:space="0" w:color="D8DCDF"/></w:tcBorders>'+
    '<w:tcMar><w:top w:w="60" w:type="dxa"/><w:bottom w:w="60" w:type="dxa"/>'+
    '<w:left w:w="90" w:type="dxa"/><w:right w:w="90" w:type="dxa"/></w:tcMar>'+
    '</w:tcPr>'+content+'</w:tc>';
}
function table(rows, widths){
  let x='<w:tbl><w:tblPr><w:tblW w:w="9640" w:type="dxa"/><w:tblLayout w:type="fixed"/>'+
        '<w:tblCellMar><w:left w:w="90" w:type="dxa"/><w:right w:w="90" w:type="dxa"/></w:tblCellMar></w:tblPr>'+
        '<w:tblGrid>'+widths.map(w=>'<w:gridCol w:w="'+w+'"/>').join("")+'</w:tblGrid>';
  x+=rows.join("");
  x+='</w:tbl>';
  return x;
}
function imagePara(rid, cx, cy, id){
  return '<w:p><w:pPr><w:spacing w:before="60" w:after="180"/></w:pPr><w:r><w:drawing>'+
   '<wp:inline distT="0" distB="0" distL="0" distR="0">'+
   '<wp:extent cx="'+cx+'" cy="'+cy+'"/><wp:effectExtent l="0" t="0" r="0" b="0"/>'+
   '<wp:docPr id="'+id+'" name="Working '+id+'"/>'+
   '<wp:cNvGraphicFramePr><a:graphicFrameLocks xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" noChangeAspect="1"/></wp:cNvGraphicFramePr>'+
   '<a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">'+
   '<a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture">'+
   '<pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">'+
   '<pic:nvPicPr><pic:cNvPr id="'+id+'" name="Working '+id+'"/><pic:cNvPicPr/></pic:nvPicPr>'+
   '<pic:blipFill><a:blip r:embed="'+rid+'"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'+
   '<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'+cx+'" cy="'+cy+'"/></a:xfrm>'+
   '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr>'+
   '</pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>';
}

const DOC_NS = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '+
  'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '+
  'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '+
  'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '+
  'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"';

const STYLES_XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
 '<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'+
 '<w:docDefaults><w:rPrDefault><w:rPr>'+
 '<w:rFonts w:ascii="Georgia" w:hAnsi="Georgia" w:cs="Georgia"/><w:sz w:val="21"/><w:szCs w:val="21"/>'+
 '</w:rPr></w:rPrDefault><w:pPrDefault><w:pPr>'+
 '<w:spacing w:after="120" w:line="260" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults>'+
 '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:qFormat/></w:style>'+
 '</w:styles>';

const CONTENT_TYPES = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
 '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'+
 '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'+
 '<Default Extension="xml" ContentType="application/xml"/>'+
 '<Default Extension="png" ContentType="image/png"/>'+
 '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'+
 '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'+
 '</Types>';

const ROOT_RELS = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
 '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+
 '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'+
 '</Relationships>';

const EMU_PER_PX = 9525;
const CONTENT_EMU = 5940000; // A4 minus 2 cm margins

function makeDocx(build){
  // build(api) pushes body XML and registers images; returns nothing
  const images=[];
  const body=[];
  const api={
    p:(runs,o)=>body.push(para(runs,o)),
    raw:x=>body.push(x),
    img:(dataUrl,w,h)=>{
      const b64=dataUrl.split(",")[1];
      const id=images.length+1;
      images.push({name:"image"+id+".png", bytes:b64ToBytes(b64)});
      let cx=w*EMU_PER_PX, cy=h*EMU_PER_PX;
      if(cx>CONTENT_EMU){ const k=CONTENT_EMU/cx; cx=Math.round(cx*k); cy=Math.round(cy*k); }
      body.push(imagePara("rIdImg"+id, Math.round(cx), Math.round(cy), 100+id));
    }
  };
  build(api);

  const docXml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
    '<w:document '+DOC_NS+'><w:body>'+body.join("")+
    '<w:sectPr><w:pgSz w:w="11906" w:h="16838"/>'+
    '<w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134" w:header="708" w:footer="708" w:gutter="0"/>'+
    '</w:sectPr></w:body></w:document>';

  let rels='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+
    '<Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>';
  images.forEach((im,i)=>{
    rels+='<Relationship Id="rIdImg'+(i+1)+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/'+im.name+'"/>';
  });
  rels+='</Relationships>';

  const files=[
    {name:"[Content_Types].xml", data:utf8(CONTENT_TYPES)},
    {name:"_rels/.rels", data:utf8(ROOT_RELS)},
    {name:"word/document.xml", data:utf8(docXml)},
    {name:"word/styles.xml", data:utf8(STYLES_XML)},
    {name:"word/_rels/document.xml.rels", data:utf8(rels)},
  ];
  images.forEach(im=>files.push({name:"word/media/"+im.name, data:im.bytes}));
  return zipStore(files);
}

