function strokesToPNG(strokes){
  if(!strokes || !strokes.length) return null;
  let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;
  strokes.forEach(st=>st.p.forEach(p=>{
    if(p[0]<x0)x0=p[0]; if(p[0]>x1)x1=p[0]; if(p[1]<y0)y0=p[1]; if(p[1]>y1)y1=p[1];
  }));
  const pad=20, w=Math.max(80,x1-x0)+pad*2, h=Math.max(50,y1-y0)+pad*2;
  const scale=Math.min(2, 1100/w);
  const c=document.createElement("canvas");
  c.width=Math.round(w*scale); c.height=Math.round(h*scale);
  const g=c.getContext("2d");
  g.fillStyle="#fff"; g.fillRect(0,0,c.width,c.height);
  g.setTransform(scale,0,0,scale,0,0); g.translate(pad-x0,pad-y0);
  g.lineCap="round"; g.lineJoin="round";
  strokes.forEach(st=>{
    const col = st.c==="ink" ? "#161B21" : st.c;
    const wAt = pr => st.w*(0.45+1.1*(pr==null?0.5:pr));
    if(st.p.length===1){
      g.fillStyle=col; g.beginPath();
      g.arc(st.p[0][0],st.p[0][1],wAt(st.p[0][2])/2,0,Math.PI*2); g.fill();
      return;
    }
    g.strokeStyle=col;
    for(let k=1;k<st.p.length;k++){
      const a=st.p[k-1], b=st.p[k];
      g.lineWidth=(wAt(a[2])+wAt(b[2]))/2;
      g.beginPath(); g.moveTo(a[0],a[1]); g.lineTo(b[0],b[1]); g.stroke();
    }
  });
  return {url:c.toDataURL("image/png"), w:c.width, h:c.height};
}

function buildExport(all){
  const list = all ? QUESTIONS : [QUESTIONS[active]];
  const nm=(document.getElementById("exName").value||"").trim();
  const d=new Date().toLocaleDateString("en-AU",{day:"numeric",month:"long",year:"numeric"});
  let h='<div class="ex-head"><div class="ex-unit">Curtin University &middot; School of Civil and Mechanical Engineering</div>'+
        '<h1>MCEN2003 Machine Dynamics &mdash; Tutorial 1: Kinematics</h1>'+
        '<div class="ex-meta"><span><b>Name:</b> '+(nm?esc(nm):"________________________")+'</span>'+
        '<span><b>Date:</b> '+d+'</span></div></div>';
  list.forEach(q=>{
    const s=qs(q);
    h+='<div class="ex-q"><h2>'+q.code+' &mdash; '+esc(q.title)+'</h2>';
    h+='<table class="ex-tab"><tr><th>Part</th><th>My answer</th><th>Result</th></tr>';
    q.parts.forEach((p,i)=>{
      const raw=s.ans[i];
      let a="—";
      if(raw!==undefined && String(raw).trim()!==""){
        a = p.choices ? (p.choices[Number(raw)]||"—") : String(raw)+(p.unit?" "+p.unit:"");
      }
      const st=s.status[i];
      const v = st==="correct" ? '<span class="ok">&#10003; correct</span>'
              : st==="wrong"   ? '<span class="bad">&#10007; incorrect</span>' : "not attempted";
      h+='<tr><td>'+esc(p.label)+'</td><td class="m">'+esc(a)+'</td><td>'+v+'</td></tr>';
    });
    h+='</table>';
    const sc=Object.create(null);
    let any=false;
    s.pages.forEach((pg,pi)=>{
      const txt=(pg.n||"").replace(/[\s]+$/,"");
      const img=strokesToPNG(pg.s);
      if(!txt.trim() && !img){ (txt||"").split("\n").forEach(evalLineIn(sc)); return; }
      any=true;
      h+='<h3>Working out &mdash; page '+(pi+1)+'</h3>';
      if(txt.trim()){
        h+='<table class="ex-work">';
        txt.split("\n").forEach(line=>{
          const body=line.split("#")[0];
          let out="";
          if(body.trim()){
            const m=body.match(/^\s*([A-Za-z_][A-Za-z_0-9]*)\s*=\s*(.+)$/);
            const r=evalLoose(m?m[2]:body.replace(/=\s*$/,""), sc);
            if(r){ if(m) sc[m[1]]=r.v; out=fmt(r.v)+(r.unit?" "+r.unit:""); }
          }
          h+='<tr><td class="m">'+esc(line||" ")+'</td><td class="m res">'+esc(out)+'</td></tr>';
        });
        h+='</table>';
      }
      if(img) h+='<img class="ex-img" src="'+img.url+'" alt="Handwritten working, page '+(pi+1)+'">';
    });
    if(!any) h+='<p class="ex-none">No working out recorded for this question.</p>';
    h+='</div>';
  });
  return h;
}
function evalLineIn(sc){ return line=>{
  const body=line.split("#")[0];
  const m=body.match(/^\s*([A-Za-z_][A-Za-z_0-9]*)\s*=\s*(.+)$/);
  if(!m) return;
  const r=evalLoose(m[2],sc); if(r) sc[m[1]]=r.v;
};}

