const MONO="Consolas", SANS="Arial";
function buildDocxBytes(all){
  const list = all ? QUESTIONS : [QUESTIONS[active]];
  const nm=(document.getElementById("exName").value||"").trim();
  const dt=new Date().toLocaleDateString("en-AU",{day:"numeric",month:"long",year:"numeric"});
  return makeDocx(api=>{
    api.p([run("Curtin University \u00B7 School of Civil and Mechanical Engineering",{color:"0F5F7D",sz:17,font:SANS})],{after:20});
    api.p([run("MCEN2003 Machine Dynamics \u2014 Tutorial 1: Kinematics",{b:1,sz:30})],{border:true,after:120});
    api.p([run("Name: ",{b:1,sz:19,font:SANS}),run(nm||"________________________",{sz:19,font:SANS}),
           run("          Date: ",{b:1,sz:19,font:SANS}),run(dt,{sz:19,font:SANS})],{after:240});
    list.forEach(q=>{
      const s=qs(q);
      api.p([run(q.code+" \u2014 "+q.title,{b:1,sz:25,color:"0F5F7D"})],{before:260,after:60,keepNext:true,border:true,borderSz:4,borderColor:"C9CFD3"});
      const hdr='<w:tr>'+
        cell(para([run("Part",{b:1,sz:16,font:SANS})],{after:0}),{w:5200,shade:"EEF3F5"})+
        cell(para([run("My answer",{b:1,sz:16,font:SANS})],{after:0}),{w:2400,shade:"EEF3F5"})+
        cell(para([run("Result",{b:1,sz:16,font:SANS})],{after:0}),{w:2040,shade:"EEF3F5"})+'</w:tr>';
      const rows=[hdr];
      q.parts.forEach((p,i)=>{
        const raw=s.ans[i];
        let a="\u2014";
        if(raw!==undefined && String(raw).trim()!=="")
          a = p.choices ? (p.choices[Number(raw)]||"\u2014") : String(raw)+(p.unit?" "+p.unit:"");
        const st=s.status[i];
        const verdict = st==="correct" ? run("\u2713 correct",{b:1,color:"1F6B45",sz:19})
                      : st==="wrong"   ? run("\u2717 incorrect",{b:1,color:"A83022",sz:19})
                                       : run("not attempted",{i:1,color:"7A858F",sz:19});
        rows.push('<w:tr>'+
          cell(para([run(p.label,{sz:19})],{after:0}),{w:5200})+
          cell(para([run(a,{font:MONO,sz:19})],{after:0}),{w:2400})+
          cell(para([verdict],{after:0}),{w:2040})+'</w:tr>');
      });
      api.raw(table(rows,[5200,2400,2040]));
      api.p([run("")],{after:0});
      const sc=Object.create(null);
      let any=false;
      s.pages.forEach((pg,pi)=>{
        const txt=(pg.n||"").replace(/\s+$/,"");
        const img=strokesToPNG(pg.s);
        if(!txt.trim() && !img){ (pg.n||"").split("\n").forEach(evalLineIn(sc)); return; }
        any=true;
        api.p([run("Working out \u2014 page "+(pi+1),{b:1,sz:16,font:SANS,color:"5A6774"})],{before:140,after:40,keepNext:true});
        if(txt.trim()) txt.split("\n").forEach(line=>{
          const body=line.split("#")[0];
          let out="";
          if(body.trim()){
            const m=body.match(/^\s*([A-Za-z_][A-Za-z_0-9]*)\s*=\s*(.+)$/);
            const r=evalLoose(m?m[2]:body.replace(/=\s*$/,""), sc);
            if(r){ if(m) sc[m[1]]=r.v; out=fmt(r.v)+(r.unit?" "+r.unit:""); }
          }
          const rs=[run(line||" ",{font:MONO,sz:18})];
          if(out) rs.push(run("        \u2192 "+out,{font:MONO,sz:18,color:"0F5F7D"}));
          api.p(rs,{after:0,line:220});
        });
        if(img) api.img(img.url, img.w, img.h);
      });
      if(!any) api.p([run("No working out recorded for this question.",{i:1,color:"7A858F",sz:19})],{before:80});
    });
  });
}
async function saveFile(filename, data, mime){
  let dl=null;
  try{ if(window.claude && typeof claude.use==="function") dl=await claude.use("downloads"); }catch(e){}
  if(dl){
    try{ await dl.save({filename, data}); return true; }
    catch(err){
      if(err && (err.code==="declined"||err.code==="rate_limited")) return false;
    }
  }
  try{
    const a=document.createElement("a");
    a.href=URL.createObjectURL(new Blob([data],{type:mime}));
    a.download=filename;
    document.body.appendChild(a); a.click();
    setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },2000);
    return true;
  }catch(e){ return false; }
}
document.getElementById("exWord").addEventListener("click",async ()=>{
  const btn=document.getElementById("exWord");
  const nm=(document.getElementById("exName").value||"my work").trim();
  btn.disabled=true; btn.textContent="Building\u2026";
  try{
    const bytes=buildDocxBytes(exAll);
    const name="MCEN2003 Tutorial 1 - "+nm.replace(/[\\/:*?\"<>|]/g,"")+".docx";
    const ok=await saveFile(name, bytes, "application/vnd.openxmlformats-officedocument.wordprocessingml.document");
    btn.textContent=ok?"Download Word (.docx)":"Download blocked \u2014 use PDF";
    if(ok) openExport(false);
  }catch(e){
    btn.textContent="Could not build \u2014 use PDF";
  }
  btn.disabled=false;
  setTimeout(()=>{ btn.textContent="Download Word (.docx)"; },4000);
});
