const sumPanel=document.getElementById("sumPanel"), sumBtn=document.getElementById("sumBtn");
function paintSummary(){
  let h='<div class="fsheet-top"><span class="label">My progress &mdash; Tutorial 1</span>'+
        '<span class="label" style="text-transform:none;letter-spacing:0;font-weight:400">Only you can see this. It lives on this device.</span></div>';
  h+='<div class="sumgrid">';
  let needHint=[], needSol=[], notDone=[], stillWrong=[];
  QUESTIONS.forEach(q=>{
    const s=qs(q);
    let tag, cls="";
    const attempted=q.parts.filter((p,i)=>s.tried[i]).length;
    const firstAll=q.parts.every((p,i)=>s.first[i]==="y");
    const allRight=q.parts.every((p,i)=>s.status[i]==="correct");
    const wrong=q.parts.filter((p,i)=>s.status[i]==="wrong").length;
    if(attempted===0){ tag="not started"; notDone.push(q.code); }
    else if(s.everSol){ tag="used the solution"; needSol.push(q.code); }
    else if(wrong){ tag=wrong+(wrong===1?" part":" parts")+" still wrong"; stillWrong.push(q.code); }
    else if(attempted<q.parts.length){ tag=attempted+" of "+q.parts.length+" attempted"; notDone.push(q.code); }
    else if(allRight && firstAll && !s.everHint){ tag="all correct, first go"; }
    else if(allRight && s.everHint){ tag="right, after the idea"; needHint.push(q.code); }
    else { tag="all correct"; }
    h+='<div class="sumrow"><span class="sumcode">'+q.code+'</span><div class="sumbar">';
    q.parts.forEach((p,i)=>{
      const c = s.first[i]==="y" ? "y" : s.status[i]==="correct" ? "n" : s.tried[i] ? "x" : "";
      h+='<span class="sumcell '+c+'" title="'+esc(p.label)+'"></span>';
    });
    h+='</div><span class="sumtag">'+tag+'</span></div>';
  });
  h+='</div>';
  h+='<div class="legend"><span><i class="sumcell y"></i> right first go</span>'+
     '<span><i class="sumcell n"></i> right after another try</span>'+
     '<span><i class="sumcell x"></i> still wrong</span>'+
     '<span><i class="sumcell"></i> not attempted</span></div>';
  let advice;
  if(notDone.length===QUESTIONS.length) advice="Nothing attempted yet. Start with T1.1 — it sets up the two-phase method the rest of the tutorial leans on.";
  else if(stillWrong.length) advice="Unfinished business on "+stillWrong.join(", ")+". Tap the red boxes — each one names the specific slip, which is faster than starting the question again.";
  else if(needSol.length) advice="Revise "+needSol.join(", ")+" first. You reached the solution on "+(needSol.length>1?"those":"that")+", which means the method has not stuck yet — work through it again on paper from a blank page, without opening the solution.";
  else if(needHint.length) advice="You got "+needHint.join(", ")+" out, but needed the idea button to start. That is the gap to close before the exam: try starting those from a blank page and see if the first step comes to you unprompted.";
  else if(notDone.length) advice="Solid so far. Still to do: "+notDone.join(", ")+".";
  else advice="Every question right without the solution. Come back a week before the exam and redo T1.1 and T1.4 from a blank page — those two carry the methods the rest of the unit builds on.";
  h+='<div class="revise"><h4>What to revise</h4><p>'+advice+'</p></div>';
  sumPanel.innerHTML=h;
}
sumBtn.addEventListener("click",()=>{
  const open=sumPanel.hidden;
  if(open) paintSummary();
  sumPanel.hidden=!open;
  sumBtn.classList.toggle("active",open);
  sumBtn.setAttribute("aria-pressed",open?"true":"false");
  if(open) sumPanel.scrollIntoView({behavior:"smooth",block:"nearest"});
});

document.getElementById("resetAll").addEventListener("click",e=>{
  const btn=e.currentTarget;
  if(btn.dataset.armed!=="1"){
    btn.dataset.armed="1"; btn.textContent="Tap again to erase everything";
    setTimeout(()=>{ btn.dataset.armed="0"; btn.textContent="Clear my work"; },4000);
    return;
  }
  store={}; save(); active=0; render();
  btn.dataset.armed="0"; btn.textContent="Clear my work";
});


/* ============================================================
   DEVICE CHECK
   ============================================================ */
(function(){
  var stamp=document.getElementById("buildStamp");
  if(stamp) stamp.textContent=BUILD_ID;
  var panel=document.getElementById("diagPanel"), btn=document.getElementById("diagBtn");
  if(!panel||!btn) return;
  var counts={down:0,move:0,up:0}, kinds={}, maxPr=0;
  function row(k,v){ return '<div class="diagrow"><b>'+k+'</b><span>'+v+'</span></div>'; }
  function yes(ok){ return ok?'<span class="pass">yes</span>':'<span class="fail">NO</span>'; }
  function paint(){
    var ls=false; try{ localStorage.setItem("__t","1"); localStorage.removeItem("__t"); ls=true; }catch(e){}
    var cv=false; try{ cv=!!document.createElement("canvas").getContext("2d"); }catch(e){}
    var h='<div class="fsheet-top"><span class="label">Device check</span>'+
          '<span class="label" style="text-transform:none;letter-spacing:0;font-weight:400">Screenshot this if something is not working.</span></div>';
    h+=row("Build", BUILD_ID);
    h+=row("Opened from", location.protocol==="file:" ? '<span class="fail">a local file</span> — scripts are often blocked; open it from Canvas or a web link instead' : location.protocol+"//"+location.host);
    h+=row("Pointer events", yes("PointerEvent" in window));
    h+=row("Canvas", yes(cv));
    h+=row("Saving your work", yes(ls));
    h+=row("Pen pressure", yes("PointerEvent" in window && "pressure" in PointerEvent.prototype));
    h+=row("Pen only mode", (typeof penOnly!=="undefined" && penOnly) ? '<span class="fail">ON — a finger will not draw</span>' : "off (anything draws)");
    h+=row("Browser", navigator.userAgent);
    h+='<p class="diagnote"><b>Now scribble in the box below — with your Pencil, and with a finger.</b> The counters must move. If they stay at zero, this device is not sending the page any drawing events, and that is what I need to know.</p>';
    h+='<canvas id="testPad"></canvas>';
    h+='<div id="testOut" class="diagnote"></div>';
    panel.innerHTML=h;
    var tp=document.getElementById("testPad"), out=document.getElementById("testOut");
    var r=tp.getBoundingClientRect(), d=Math.min(window.devicePixelRatio||1,2.5);
    tp.width=Math.round(r.width*d); tp.height=Math.round(r.height*d);
    var g=tp.getContext("2d"); g.setTransform(d,0,0,d,0,0);
    g.lineCap="round"; g.lineJoin="round"; g.strokeStyle=inkColor();
    var on=false,last=null;
    function report(){
      out.innerHTML="down: <b>"+counts.down+"</b> &nbsp; move: <b>"+counts.move+"</b> &nbsp; up: <b>"+counts.up+
        "</b><br>input seen: <b>"+(Object.keys(kinds).join(", ")||"none yet")+
        "</b><br>highest pressure: <b>"+maxPr.toFixed(2)+"</b>";
    }
    function xy(e){ var b=tp.getBoundingClientRect(); return [e.clientX-b.left, e.clientY-b.top]; }
    tp.addEventListener("pointerdown",function(e){
      e.preventDefault(); counts.down++; kinds[e.pointerType]=1;
      if(e.pressure>maxPr) maxPr=e.pressure;
      on=true; last=xy(e);
      g.lineWidth=1+4*(e.pressure||0.5);
      g.fillStyle=inkColor();
      g.beginPath(); g.arc(last[0],last[1],g.lineWidth/2,0,Math.PI*2); g.fill();
      report();
    },{passive:false});
    tp.addEventListener("pointermove",function(e){
      if(!on) return; e.preventDefault(); counts.move++;
      if(e.pressure>maxPr) maxPr=e.pressure;
      var p=xy(e);
      g.lineWidth=1+4*(e.pressure||0.5);
      g.beginPath(); g.moveTo(last[0],last[1]); g.lineTo(p[0],p[1]); g.stroke();
      last=p; report();
    },{passive:false});
    ["pointerup","pointercancel"].forEach(function(t){
      tp.addEventListener(t,function(){ if(on){ on=false; counts.up++; report(); } });
    });
    tp.addEventListener("touchstart",function(){ kinds["raw-touch"]=1; report(); },{passive:true});
    report();
  }
  btn.addEventListener("click",function(){
    var open=panel.hidden;
    if(open) paint();
    panel.hidden=!open;
    btn.classList.toggle("active",open);
    if(open) panel.scrollIntoView({block:"nearest"});
  });
})();

try{
  render();
  calcLive();
}catch(err){
  showErr("STARTUP FAILED: " + ((err && (err.stack||err.message)) || err));
}
